  const playNotifChime = () => {
    if (typeof window === "undefined") return;
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const now = ctx.currentTime;
      const notes = [698.46, 880, 1046.5, 1318.51, 1760];
      const stagger = 0.08;
      notes.forEach((freq, index) => {
        const noteTime = now + index * stagger;
        const osc1 = ctx.createOscillator();
        osc1.type = "sine";
        osc1.frequency.setValueAtTime(freq, noteTime);
        const osc2 = ctx.createOscillator();
        osc2.type = "sine";
        osc2.frequency.setValueAtTime(freq * 2, noteTime);
        const noteGain = ctx.createGain();
        noteGain.gain.setValueAtTime(0, noteTime);
        noteGain.gain.linearRampToValueAtTime(0.18 - index * 0.02, noteTime + 8e-3);
        noteGain.gain.exponentialRampToValueAtTime(5e-4, noteTime + 1.6);
        const wave1Gain = ctx.createGain();
        wave1Gain.gain.setValueAtTime(0.75, noteTime);
        const wave2Gain = ctx.createGain();
        wave2Gain.gain.setValueAtTime(0.25, noteTime);
        osc1.connect(wave1Gain);
        wave1Gain.connect(noteGain);
        osc2.connect(wave2Gain);
        wave2Gain.connect(noteGain);
        noteGain.connect(ctx.destination);
        osc1.start(noteTime);
        osc1.stop(noteTime + 1.8);
        osc2.start(noteTime);
        osc2.stop(noteTime + 1.8);
      });
    } catch (err) {
      console.warn("Synth audio feedback blocked or unsupported:", err);
    }
  };
