  const handleToggleNotificationRead = async (id: string) => {
    const target = (notifications as any[]).find((n: any) => n.id === id);
    if (!target) return;
    const newStatus = target.status === 'unread' ? 'read' : 'unread';
    setNotifications((prev: any) => prev.map((n: any) => n.id === id ? { ...n, status: newStatus } : n));
    try {
      await updateDoc(doc(db, 'notifications', id), { status: newStatus });
    } catch (err) {
      console.error("Error updating notification status:", err);
    }
  };

