  const sendFieldTaskCompletedWhatsApp = async (broker: Broker, task: BrokerTask) => {
    if (!isFieldTaskStatusWaNotifEnabled || !task.appointmentId) return;
    try {
      const appt = appointments.find(a => a.id === task.appointmentId);
      if (appt && appt.clientPhone) {
        const clientName = appt.clientName || "العميل الكريم";
        const clientPhone = appt.clientPhone;
        const brokerName = broker.name || "المندوب";
        const taskTitle = task.title || "المهمة الميدانية";
        
        // Render Template
        const templateMessage = notifTemplates.field_task_completed?.message || 
          "عزيزنا العميل {clientName}، نود إعلامكم بأن المندوب/الوسيط {broker} قد أتم بنجاح مهمة العمل الميدانية: \"{taskTitle}\" بنجاح في موقع العقار/المشروع. شكراً لثقتكم بنا! شركة البراء النعيمي للتسويق العقاري.";
        
        const title = notifTemplates.field_task_completed?.title || "تنبيه إنجاز مهمة ميدانية 📋";
        
        const renderedMessage = `*${title}*\n\n` + templateMessage
          .replace(/{clientName}/g, clientName)
          .replace(/{broker}/g, brokerName)
          .replace(/{taskTitle}/g, taskTitle);

        // Dispatch WhatsApp
        const res = await authFetch("/api/whatsapp/send", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ phone: clientPhone, message: renderedMessage })
        });
        const data = await res.json();
        
        // Log to Firestore whatsapp_logs
        const logRef = doc(collection(db, 'whatsapp_logs'));
        await setDoc(logRef, {
          id: logRef.id,
          clientPhone,
          clientName,
          message: renderedMessage,
          status: data.success ? 'delivered' : 'failed',
          timestamp: new Date().toISOString(),
          type: 'field_task_status_alert',
          brokerId: broker.id,
          taskId: task.id
        });
        console.log("Successfully sent field task completion alert via WhatsApp.");
      }
    } catch (err) {
      console.error("Error in sendFieldTaskCompletedWhatsApp:", err);
    }
  };

  const handleUpdateBrokerTaskStatus = async (brokerId: string, taskId: string, newStatus: 'in_progress' | 'completed' | 'disabled') => {
    try {
      const brokerDocRef = doc(db, 'brokers', brokerId);
      const brokerDoc = await getDoc(brokerDocRef);
      if (!brokerDoc.exists()) return;
      const broker = brokerDoc.data() as Broker;
      const tasks = broker.tasks || [];
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status: newStatus, completedAt: newStatus === 'completed' ? new Date().toISOString() : undefined } : t);
      await updateDoc(brokerDocRef, { tasks: updatedTasks });
      fetchBrokers();

      if (newStatus === 'completed') {
        const completedTask = tasks.find(t => t.id === taskId);
        if (completedTask) {
          sendFieldTaskCompletedWhatsApp(broker, completedTask);
        }
      }
    } catch (err) {
      console.error("Error updating broker task:", err);
      alert("فشل في تحديث حالة المهمة.");
    }
  };

