  /**
   * Firestore rules only grant appointment reads to admins (collection query)
   * or to the owning client (filtered query). An unfiltered `getDocs` therefore
   * fails for regular users, so the query shape has to follow the principal.
   * Clients that are not signed in get an empty list rather than an error.
   */
  const buildAppointmentsQuery = () => {
    if (userProfile?.role === 'admin') {
      return collection(db, 'appointments');
    }
    const uid = currentUser?.uid;
    if (!uid) return null;
    return query(collection(db, 'appointments'), where('userId', '==', uid));
  };

  const fetchAppointments = async () => {
    try {
      const target = buildAppointmentsQuery();
      if (!target) {
        setAppointments([]);
        return;
      }
      const qSnapshot = await getDocs(target);
      const list: Appointment[] = [];
      qSnapshot.forEach((doc) => {
        list.push({ id: doc.id, ...doc.data() } as Appointment);
      });
      setAppointments(list);
    } catch (err) {
      console.error("Error fetching appointments:", err);
    }
  };

