  const handleSendWelcomeMessage = async (client: any) => {
    try {
      const clientName = client.name || 'عميلنا العزيز';
      const clientPhone = client.phone || '';
      const clientEmail = client.email || '';

      // Check if there is an existing support chat for this user
      const existingChat = supportChats.find(chat => 
        (chat.userPhone && clientPhone && chat.userPhone.replace(/\s+/g, '').includes(clientPhone.replace(/\s+/g, ''))) ||
        (chat.userName && chat.userName.includes(clientName))
      );

      const welcomeText = `أهلاً بك يا ${clientName}! سعداء جداً بتعاملك المستمر وثقتك بشركة البراء النعيمي العقارية. يسعدنا تقديم أفضل الخدمات والعروض العقارية الحصرية لك دائماً. ✨🌸`;

      const newMsg = {
        id: Math.random().toString(36).substring(7),
        sender: 'team',
        text: welcomeText,
        createdAt: new Date().toISOString()
      };

      if (existingChat) {
        const updatedMessages = [...(existingChat.messages || []), newMsg];
        await updateDoc(doc(db, 'support_chats', existingChat.id), {
          messages: updatedMessages,
          lastMessage: welcomeText,
          lastActive: new Date().toISOString(),
          tag: 'followed_up',
          status: 'open'
        });
      } else {
        await addDoc(collection(db, 'support_chats'), {
          userName: clientName,
          userPhone: clientPhone || clientEmail || 'غير متوفر',
          status: 'open',
          tag: 'followed_up',
          lastMessage: welcomeText,
          lastActive: new Date().toISOString(),
          messages: [newMsg]
        });
      }

      alert(`تم إرسال الرسالة الترحيبية الخاصة بنجاح للعميل ${clientName}! ✉️✅`);
    } catch (err) {
      console.error("Error sending welcome message:", err);
      alert("حدث خطأ أثناء إرسال الرسالة الترحيبية.");
    }
  };

