  const handleSimulateIncomingMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!simulatedPhone.trim() || !simulatedMessage.trim()) {
      alert("يرجى إدخال رقم الهاتف ونص الرسالة للمحاكاة.");
      return;
    }

    setSimulatingIncoming(true);
    try {
      const incomingDoc = await addDoc(collection(db, 'whatsapp_incoming'), {
        name: simulatedName.trim() || "عميل محاكي",
        phone: simulatedPhone.trim(),
        message: simulatedMessage.trim(),
        createdAt: new Date().toISOString(),
        replied: false
      });

      const lowerMsg = simulatedMessage.trim().toLowerCase();
      const matchedRule = whatsappRules.find(rule => {
        if (!rule.active) return false;
        const keywords = (rule.keywords || '').toLowerCase().split(',').map((k: string) => k.trim());
        if (rule.matchType === 'exact') {
          return keywords.some((kw: string) => lowerMsg === kw);
        } else {
          return keywords.some((kw: string) => lowerMsg.includes(kw));
        }
      });

      if (matchedRule) {
        await addDoc(collection(db, 'whatsapp_logs'), {
          phone: simulatedPhone.trim(),
          message: matchedRule.replyText,
          type: 'outgoing',
          status: 'delivered',
          provider: 'auto_rule',
          createdAt: new Date().toISOString()
        });

        await updateDoc(doc(db, 'whatsapp_incoming', incomingDoc.id), {
          replied: true,
          replyText: matchedRule.replyText,
          repliedAt: new Date().toISOString()
        });

        alert(`تم استلام رسالة المحاكاة بنجاح وتفعيل الرد التلقائي للمطابقة: "${matchedRule.replyText}" 🤖`);
      } else {
        alert("تم استلام رسالة المحاكاة بنجاح (لم تطابق أي قواعد رد تلقائي). 📥");
      }

      setSimulatedMessage('');
      fetchWhatsAppIncomingMessages();
      fetchWhatsAppLogs();
    } catch (err) {
      console.error("Error simulating message:", err);
      alert("فشل محاكاة استلام الرسالة.");
    } finally {
      setSimulatingIncoming(false);
    }
  };

  const handleSaveRule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!ruleKeywords.trim() || !ruleReplyText.trim()) {
      alert("يرجى ملء الكلمات المفتاحية ونص الرد التلقائي.");
      return;
    }

    setIsSavingRule(true);
    try {
      const data = {
        keywords: ruleKeywords.trim(),
        replyText: ruleReplyText.trim(),
        matchType: ruleMatchType,
        active: ruleActive,
        updatedAt: new Date().toISOString()
      };

      if (editingRule) {
        await updateDoc(doc(db, 'whatsapp_rules', editingRule.id), data);
        alert("تم تحديث قاعدة الرد التلقائي بنجاح! 🤖");
      } else {
        await addDoc(collection(db, 'whatsapp_rules'), {
          ...data,
          createdAt: new Date().toISOString()
        });
        alert("تمت إضافة قاعدة رد تلقائي جديدة! 🤖");
      }

      setShowRuleModal(false);
      setEditingRule(null);
      setRuleKeywords('');
      setRuleReplyText('');
      setRuleMatchType('contains');
      setRuleActive(true);
      fetchWhatsAppRules();
    } catch (err) {
      console.error("Error saving rule:", err);
      alert("فشل حفظ قاعدة الرد التلقائي.");
    } finally {
      setIsSavingRule(false);
    }
  };

