  const simulateTestWebhookLog = async () => {
    const targets = [
      { name: 'قسم المبيعات والتسويق العقاري', url: 'https://crm.syrian-realestate.com/api/v1/webhook/sales' },
      { name: 'خدمة التوثيق القانوني والطابو', url: 'https://legal.syrian-hub.org/webhook/legal-sync' },
      { name: 'مجموعة واتساب الطوارئ والصيانة', url: 'https://api.whatsapp-gateway.net/v2/send-group' },
      { name: 'قسم إدارة العقارات والإيجارات', url: 'https://property-mgr.sy/api/webhook' }
    ];
    const randomTarget = targets[Math.floor(Math.random() * targets.length)];
    const isSuccess = Math.random() > 0.2;
    const statusCode = isSuccess ? (Math.random() > 0.5 ? 200 : 201) : (Math.random() > 0.5 ? 500 : 400);
    const latencyMs = Math.floor(Math.random() * 400) + 75;

    const newLog = {
      id: `log_sim_${Date.now()}`,
      webhookName: randomTarget.name,
      url: randomTarget.url,
      method: 'POST',
      statusCode: statusCode,
      latencyMs: latencyMs,
      createdAt: new Date().toISOString(),
      success: isSuccess,
      responsePreview: isSuccess ? '{"status":"success","received":true,"code":200}' : '{"error":"endpoint_error","status":500}',
      payload: JSON.stringify({ event: 'manual_ping_test', timestamp: new Date().toISOString(), trigger: 'admin_dashboard' }, null, 2)
    };

    try {
      await addDoc(collection(db, 'webhook_logs'), {
        ...newLog,
        createdAt: new Date().toISOString()
      });
    } catch (e) {
      console.error("Firestore log add error:", e);
    }

    setWebhookLogs(prev => [newLog, ...prev]);
  };

