  const handleTestSubWebhook = async (id: string, url: string, method: string, deptName?: string, serviceTitle?: string, customMsg?: string) => {
    if (!url) {
      alert("يرجى إدخال رابط الـ Webhook أولاً قبل إجراء الاختبار!");
      return;
    }
    const msg = customMsg || testPingMessage || "رسالة تجريبية مخصصة لفحص توافق واستجابة الـ Webhook الفرعي";
    setTestPingStatuses(prev => ({
      ...prev,
      [id]: { loading: true }
    }));

    const sentPayload = {
      event: "department_notification",
      timestamp: new Date().toISOString(),
      department: deptName || null,
      service: serviceTitle || null,
      message: msg,
      data: {
        phone: "963945430030",
        status: "simulated_test"
      }
    };

    const startTime = performance.now();

    try {
      const res = await authFetch('/api/whatsapp/test-sub-webhook', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          id, 
          type: deptName ? 'dept' : 'service', 
          url, 
          method, 
          departmentName: deptName, 
          serviceTitle, 
          message: msg 
        })
      });
      const data = await res.json();
      const endTime = performance.now();
      const latency = Math.round(endTime - startTime);

      setTestPingStatuses(prev => ({
        ...prev,
        [id]: {
          loading: false,
          success: data.success,
          status: data.status,
          error: data.success ? undefined : (data.error || `Error Code: ${data.status}`),
          latency
        }
      }));

      // Add to running history logs
      setTestPingLogs(prev => [
        {
          id: Date.now().toString() + Math.random().toString(36).substring(2, 7),
          timestamp: new Date().toLocaleTimeString('ar-SY', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          targetName: deptName || serviceTitle || `معرف: ${id}`,
          type: deptName ? '🏢 قسم إداري' : '🏡 خدمة عقارية',
          url,
          method,
          payload: sentPayload,
          success: data.success,
          status: data.status || (data.success ? 200 : 500),
          error: data.success ? undefined : (data.error || `Error Code: ${data.status}`),
          latency
        },
        ...prev
      ]);
    } catch (err: any) {
      const endTime = performance.now();
      const latency = Math.round(endTime - startTime);

      setTestPingStatuses(prev => ({
        ...prev,
        [id]: {
          loading: false,
          success: false,
          error: err.message,
          latency
        }
      }));

      setTestPingLogs(prev => [
        {
          id: Date.now().toString() + Math.random().toString(36).substring(2, 7),
          timestamp: new Date().toLocaleTimeString('ar-SY', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          targetName: deptName || serviceTitle || `معرف: ${id}`,
          type: deptName ? '🏢 قسم إداري' : '🏡 خدمة عقارية',
          url,
          method,
          payload: sentPayload,
          success: false,
          status: 'ERR',
          error: err.message,
          latency
        },
        ...prev
      ]);
    }
  };

