  const detectAppointmentConflicts = (apps: any[]) => {
    const conflicts: Record<string, any[]> = {};
    const activeApps = apps.filter(a => !a.archived && a.status !== 'cancelled');
    
    for (let i = 0; i < activeApps.length; i++) {
      for (let j = i + 1; j < activeApps.length; j++) {
        const app1 = activeApps[i];
        const app2 = activeApps[j];
        
        if (app1.date === app2.date && app1.time === app2.time) {
          if (!conflicts[app1.id]) conflicts[app1.id] = [];
          if (!conflicts[app2.id]) conflicts[app2.id] = [];
          conflicts[app1.id].push(app2);
          conflicts[app2.id].push(app1);
        }
      }
    }
    return conflicts;
  };

