  const filteredAllPropertiesForAdmin = useMemo(() => {
    return allProperties.filter(p => {
      // 1. Text Search Query (Title, code, ID, description, governorate, region, location)
      if (adminPropertySearchQuery.trim()) {
        const qStr = adminPropertySearchQuery.toLowerCase();
        const matchesId = (p.id || '').toLowerCase().includes(qStr);
        const matchesTitle = (p.title || '').toLowerCase().includes(qStr);
        const matchesName = (p.name || '').toLowerCase().includes(qStr);
        const matchesDesc = (p.description || '').toLowerCase().includes(qStr);
        const matchesRef = (p.refNo || '').toLowerCase().includes(qStr);
        const matchesGov = (p.governorate || '').toLowerCase().includes(qStr);
        const matchesReg = (p.region || '').toLowerCase().includes(qStr);
        const matchesLoc = (p.location || '').toLowerCase().includes(qStr);
        if (!matchesId && !matchesTitle && !matchesName && !matchesDesc && !matchesRef && !matchesGov && !matchesReg && !matchesLoc) {
          return false;
        }
      }

      // 2. Min Price Filter
      if (adminMinPriceFilter) {
        const minVal = parseFloat(adminMinPriceFilter);
        if (!isNaN(minVal) && parsePriceToNumber(p.price) < minVal) return false;
      }

      // 3. Max Price Filter
      if (adminMaxPriceFilter) {
        const maxVal = parseFloat(adminMaxPriceFilter);
        if (!isNaN(maxVal) && parsePriceToNumber(p.price) > maxVal) return false;
      }

      // 4. Property Type Filter (Residential, Commercial, Land)
      if (adminPropertyTypeFilter !== 'all') {
        const typeStr = p.type || 'Residential';
        if (typeStr.toLowerCase() !== adminPropertyTypeFilter.toLowerCase()) return false;
      }

      // 5. Governorate Filter
      if (adminGovernorateFilter !== 'all') {
        const govStr = p.governorate || 'دمشق';
        if (govStr !== adminGovernorateFilter) return false;
      }

      // 6. Region Search/Filter
      if (adminRegionFilter.trim()) {
        const regQuery = adminRegionFilter.toLowerCase().trim();
        const matchesReg = (p.region || '').toLowerCase().includes(regQuery);
        const matchesSubDist = (p.subDistrict || '').toLowerCase().includes(regQuery);
        const matchesLoc = (p.location || '').toLowerCase().includes(regQuery);
        if (!matchesReg && !matchesSubDist && !matchesLoc) return false;
      }

      // 7. Property Classification
      if (adminPropertyClassificationFilter !== 'all' && p.classification !== adminPropertyClassificationFilter) return false;

      // 8. Block Status
      if (adminPropertyBlockFilter !== 'all') {
        const isBlocked = !!p.blocked || !!p.isBlocked;
        if (adminPropertyBlockFilter === 'blocked' && !isBlocked) return false;
        if (adminPropertyBlockFilter === 'unblocked' && isBlocked) return false;
      }

      // 9. Verification & Exclusivity Status
      if (adminPropertyVerificationFilter !== 'all') {
        const isExclusive = !!p.isExclusive;
        const isVerified = !!p.verified || !!p.isExclusive;
        if (adminPropertyVerificationFilter === 'exclusive' && !isExclusive) return false;
        if (adminPropertyVerificationFilter === 'regular' && isExclusive) return false;
        if (adminPropertyVerificationFilter === 'pending_review' && p.status !== 'pending_review') return false;
      }

      return true;
    });
  }, [
    allProperties,
    adminPropertySearchQuery,
    adminMinPriceFilter,
    adminMaxPriceFilter,
    adminPropertyClassificationFilter,
    adminPropertyBlockFilter,
    adminPropertyVerificationFilter,
    adminPropertyTypeFilter,
    adminGovernorateFilter,
    adminRegionFilter
  ]);

