  const handleCompleteBrokerTask = async (taskId: string, status: 'completed' | 'disabled' = 'completed', notes?: string) => {
    if (!selectedBrokerForTasks) return;
    try {
      const updatedTasks = (selectedBrokerForTasks.tasks || []).map((t: BrokerTask) => {
        if (t.id === taskId) {
          return {
            ...t,
            status: status,
            notes: (notes || completionNotes).trim(),
            workPhotos: status === 'completed' ? taskCompletedPhotos : [],
            completedAt: status === 'completed' ? new Date().toISOString() : undefined
          };
        }
        return t;
      });

      await updateDoc(doc(db, 'brokers', selectedBrokerForTasks.id), {
        tasks: updatedTasks
      });

      setSelectedBrokerForTasks(prev => prev ? { ...prev, tasks: updatedTasks } : null);
      setCompletingTaskId(null);
      setCompletionNotes('');
      setTaskCompletedPhotos([]);
      setSuccessMessage(status === 'completed' ? "تم إنجاز وتوثيق المهمة بنجاح! ✅" : "تم تعطيل المهمة بنجاح! 🚫");
      setTimeout(() => setSuccessMessage(null), 3000);
      fetchBrokers();

      if (status === 'completed') {
        const completedTask = (selectedBrokerForTasks.tasks || []).find((t: BrokerTask) => t.id === taskId);
        if (completedTask) {
          sendFieldTaskCompletedWhatsApp(selectedBrokerForTasks, completedTask);
        }
      }
    } catch (err) {
      console.error("Error updating broker task:", err);
      alert("فشل في تحديث حالة المهمة.");
    }
  };

  const handleAssignBrokerTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBrokerForTasks) return;
    if (!newBrokerTaskTitle.trim()) {
      alert("يرجى إدخال عنوان المهمة.");
      return;
    }

    if (selectedCategoryId) {
      const selectedCategory = taskCategories.find(cat => cat.id === selectedCategoryId);
      if (selectedCategory) {
        const categoryName = selectedCategory.name.trim();
        const allSpecialtyNames = [
          'إكساء',
          'تمديدات كهربائية',
          'تمديدات صحية',
          'ديكور',
          ...(technicalSpecialties || []).map(spec => spec.name.trim())
        ];

        const isSpecialtyTask = allSpecialtyNames.some(specName => 
          specName.toLowerCase() === categoryName.toLowerCase()
        );

        if (isSpecialtyTask) {
          const brokerSpecs = selectedBrokerForTasks.specialties || [];
          const hasRequiredSpecialty = brokerSpecs.some((s: string) => 
            s.trim().toLowerCase() === categoryName.toLowerCase() ||
            s.trim().toLowerCase().includes(categoryName.toLowerCase()) ||
            categoryName.toLowerCase().includes(s.trim().toLowerCase())
          );

          if (!hasRequiredSpecialty) {
            alert(`⚠️ لا يمكن إسناد هذه المهمة للوسيط/المندوب لأنها تتطلب تخصص "${categoryName}" وهو غير مسجل في مصفوفة تخصصاته الفنية المعتمدة.`);
            return;
          }
        }
      }
    }

    if (!selectedTaskDeptId || !selectedTaskSubDeptId) {
      alert("❌ يرجى اختيار القسم الإداري الرئيسي والقسم الفرعي التابع لتلك المهمة.");
      return;
    }

    const dept = departments.find(d => d.id === selectedTaskDeptId);
    const subDept = dept?.subDepartments?.find(sd => sd.id === selectedTaskSubDeptId);

    const newTask: BrokerTask = {
      id: `task_${Date.now()}`,
      title: newBrokerTaskTitle.trim(),
      status: 'in_progress',
      createdAt: new Date().toISOString(),
      dueDate: newBrokerTaskDueDate || undefined,
      dueTime: newBrokerTaskDueTime || undefined,
      categoryId: selectedCategoryId || undefined,
      departmentId: selectedTaskDeptId || undefined,
      departmentName: dept?.name || undefined,
      subDepartmentId: selectedTaskSubDeptId || undefined,
      subDepartmentName: subDept?.name || undefined,
    };

    try {
      const updatedTasks = [...(selectedBrokerForTasks.tasks || []), newTask];
      await updateDoc(doc(db, 'brokers', selectedBrokerForTasks.id), {
        tasks: updatedTasks
      });

      setSelectedBrokerForTasks(prev => prev ? { ...prev, tasks: updatedTasks } : null);
      setNewBrokerTaskTitle('');
      setNewBrokerTaskDueDate('');
      setNewBrokerTaskDueTime('');
      setSelectedCategoryId('');
      setSelectedTaskDeptId('');
      setSelectedTaskSubDeptId('');
      setSuccessMessage("تم إسناد المهمة للوسيط بنجاح! 📋");
      setTimeout(() => setSuccessMessage(null), 3000);
      fetchBrokers();
    } catch (err) {
      console.error("Error assigning broker task:", err);
      alert("فشل في إسناد المهمة.");
    }
  };
