  const handleFlagPhotoForReview = async (brokerId: string, taskId: string, photoUrl: string, feedback: string) => {
    if (brokerId === 'mock') {
      setMockPhotoReviews(prev => ({
        ...prev,
        [photoUrl]: { reviewRequired: true, reviewNotes: feedback }
      }));
      setSuccessMessage('تم وضع إشارة (مراجعة مطلوبة) على الصورة النموذجية بنجاح! 🔔');
      setTimeout(() => setSuccessMessage(null), 3500);
      return;
    }

    try {
      const brokerDocRef = doc(db, 'brokers', brokerId);
      const brokerDoc = await getDoc(brokerDocRef);
      if (!brokerDoc.exists()) return;
      
      const brokerData = brokerDoc.data();
      const tasks = brokerData.tasks || [];
      const updatedTasks = tasks.map((t: any) => {
        if (t.id === taskId) {
          const flaggedPhotos = t.flaggedPhotos || [];
          return {
            ...t,
            reviewRequired: true,
            reviewNotes: feedback,
            reviewRequestedAt: new Date().toISOString(),
            flaggedPhotos: flaggedPhotos.includes(photoUrl) ? flaggedPhotos : [...flaggedPhotos, photoUrl]
          };
        }
        return t;
      });

      await updateDoc(brokerDocRef, { tasks: updatedTasks });
      
      const notifRef = collection(db, 'notifications');
      await addDoc(notifRef, {
        userId: brokerId,
        title: '⚠️ مراجعة مطلوبة للعمل الميداني',
        body: `يرجى إعادة تصوير مهمة "${updatedTasks.find((t: any) => t.id === taskId)?.title}". السبب: ${feedback}`,
        type: 'warning',
        read: false,
        createdAt: new Date().toISOString()
      });

      setSuccessMessage('تم وضع إشارة (مراجعة مطلوبة) وإرسال التنبيه للمندوب بنجاح! 🔔');
      setTimeout(() => setSuccessMessage(null), 3500);
      fetchBrokers();
    } catch (err) {
      console.error("Error flagging photo for review:", err);
      alert('حدث خطأ أثناء حفظ طلب المراجعة.');
    }
  };
