  const handleAddOrUpdateSubDepartment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!targetParentDeptId) return;
    if (!subDeptName.trim() || !subDeptSupervisor.trim() || !subDeptPhone.trim()) {
      alert("❌ يرجى تعبئة كافة الحقول المطلوبة (الاسم، المشرف، هاتف الاتصال).");
      return;
    }

    const parentDept = departments.find(d => d.id === targetParentDeptId);
    if (!parentDept) return;

    let subList = parentDept.subDepartments ? [...parentDept.subDepartments] : [];

    const newSubData: SubDepartment = {
      id: editingSubDept ? editingSubDept.id : `sub_${Date.now()}`,
      name: subDeptName.trim(),
      supervisorName: subDeptSupervisor.trim(),
      supervisorPhone: subDeptPhone.trim(),
      supervisorEmail: subDeptEmail.trim(),
      description: subDeptDescription.trim(),
      permissions: subDeptPermissions,
      tasks: editingSubDept ? (editingSubDept.tasks || []) : [],
      createdAt: editingSubDept ? editingSubDept.createdAt : new Date().toISOString()
    };

    if (editingSubDept) {
      subList = subList.map(item => item.id === editingSubDept.id ? newSubData : item);
    } else {
      subList.push(newSubData);
    }

    try {
      await updateDoc(doc(db, 'departments', targetParentDeptId), {
        subDepartments: subList
      });

      setDepartments(prev => prev.map(d => d.id === targetParentDeptId ? { ...d, subDepartments: subList } : d));
      setSuccessMessage(editingSubDept ? "تم تحديث القسم الفرعي وصلاحياته بنجاح! ✔️" : "تم إنشاء القسم الفرعي وتعيينه بنجاح! 🎉");
      
      // Reset State
      setShowAddSubDeptModal(false);
      setTargetParentDeptId(null);
      setEditingSubDept(null);
      setSubDeptName('');
      setSubDeptSupervisor('');
      setSubDeptPhone('');
      setSubDeptEmail('');
      setSubDeptDescription('');
      setSubDeptPermissions([]);

      setTimeout(() => setSuccessMessage(null), 3000);
    } catch (err) {
      console.error("Error updating subdepartment: ", err);
      alert("فشل في حفظ وتخزين القسم الفرعي الجديد بقاعدة البيانات.");
    }
  };

