  const handleAddTaskToSubDepartment = async (parentDeptId: string, subDeptId: string) => {
    if (!newTaskTitle.trim()) {
      alert("❌ يرجى إدخال عنوان المهمة المراد تعيينها.");
      return;
    }

    const parentDept = departments.find(d => d.id === parentDeptId);
    if (!parentDept) return;

    const subList = parentDept.subDepartments ? [...parentDept.subDepartments] : [];
    const subIdx = subList.findIndex(item => item.id === subDeptId);
    if (subIdx === -1) return;

    const assignedEmployee = newTaskAssignedTo.trim() || subList[subIdx].supervisorName;
    const currentTasks = subList[subIdx].tasks ? [...(subList[subIdx].tasks || [])] : [];
    currentTasks.push({
      id: `task_${Date.now()}`,
      title: newTaskTitle.trim(),
      assignedTo: assignedEmployee,
      status: 'pending',
      subCategoryId: selectedSubCategoryId || undefined
    });

    subList[subIdx] = {
      ...subList[subIdx],
      tasks: currentTasks
    };

    try {
      await updateDoc(doc(db, 'departments', parentDeptId), {
        subDepartments: subList
      });

      // If auto-scheduling is enabled, add it to the company calendar (appointments collection)
      if (subDeptTaskAutoSchedule) {
        const scheduledApp = {
          clientName: `مهمة: ${newTaskTitle.trim()}`,
          clientEmail: subList[subIdx].supervisorEmail || 'info@alnaimi.com',
          clientPhone: subList[subIdx].supervisorPhone || '0945430030',
          date: subDeptTaskScheduleDate,
          time: subDeptTaskScheduleTime,
          serviceTitle: `تكليف قسم: ${parentDept.name} -> ${subList[subIdx].name} (المسؤول: ${assignedEmployee})`,
          status: 'confirmed',
          userId: auth.currentUser?.uid || 'admin',
          createdAt: new Date().toISOString(),
          paymentMethod: 'free',
          isSubTaskSchedule: true
        };
        await addDoc(collection(db, 'appointments'), scheduledApp);
        
        // Automated WhatsApp Notification
        const broker = brokers.find(b => b.name === assignedEmployee);
        if (broker && broker.phone) {
            const msg = `تم إسناد مهمة جديدة لك: ${newTaskTitle.trim()}. الموعد النهائي: ${subDeptTaskScheduleDate} ${subDeptTaskScheduleTime}.`;
            alert(`[واتساب تلقائي] تم إرسال الرسالة للمندوب ${broker.name}: ${msg}`);
        }
      }

      setDepartments(prev => prev.map(d => d.id === parentDeptId ? { ...d, subDepartments: subList } : d));
      setAddingTaskForSubDeptId(null);
      setNewTaskTitle('');
      setNewTaskAssignedTo('');
      setSubDeptTaskAutoSchedule(false);
      setSubDeptTaskScheduleDate(format(new Date(), 'yyyy-MM-dd'));
      setSubDeptTaskScheduleTime('10:00');
      setSelectedSubCategoryId('');
      setSuccessMessage("تمت إضافة المهمة بنجاح وتعيينها للقسم الفرعي! 📌");
      setTimeout(() => setSuccessMessage(null), 3000);
    } catch (err) {
      console.error("Error adding task:", err);
      alert("فشل في تعيين المهمة الجديدة.");
    }
  };

  const handleToggleTaskStatus = async (parentDeptId: string, subDeptId: string, taskId: string, currentStatus: 'pending' | 'completed') => {
    const parentDept = departments.find(d => d.id === parentDeptId);
    if (!parentDept) return;

    const subList = parentDept.subDepartments ? [...parentDept.subDepartments] : [];
    const subIdx = subList.findIndex(item => item.id === subDeptId);
    if (subIdx === -1) return;

    const currentTasks = subList[subIdx].tasks ? subList[subIdx].tasks.map(t => {
      if (t.id === taskId) {
        return { ...t, status: (currentStatus === 'pending' ? 'completed' : 'pending') as 'pending' | 'completed' };
      }
      return t;
    }) : [];

    subList[subIdx] = {
      ...subList[subIdx],
      tasks: currentTasks
    };

    try {
      await updateDoc(doc(db, 'departments', parentDeptId), {
        subDepartments: subList
      });

      setDepartments(prev => prev.map(d => d.id === parentDeptId ? { ...d, subDepartments: subList } : d));
      setSuccessMessage("تم تعديل حالة المهمة وتحديث تقدم القسم بنجاح! ✔️");
      setTimeout(() => setSuccessMessage(null), 3000);
    } catch (err) {
      console.error("Error toggling task status:", err);
    }
  };

