  const handleSaveLeadNotes = async (targetUid?: string, clientPhoneOrEmail?: string) => {
    setIsSavingLeadNotes(true);
    setLeadNotesSaveSuccess(false);
    try {
      const updatedTimestamp = new Date().toISOString();
      const updaterName = userProfile?.name || 'مستشار عقاري';
      const trimmedNotes = leadPrivateNotes.trim();

      // Resolve target UID
      let resolvedUid = targetUid;
      if (!resolvedUid && clientPhoneOrEmail) {
        const found = users.find(u => 
          (u.phone && u.phone === clientPhoneOrEmail) || 
          (u.email && u.email === clientPhoneOrEmail) ||
          u.uid === clientPhoneOrEmail
        );
        if (found) {
          resolvedUid = found.uid;
        }
      }

      if (resolvedUid) {
        await updateDoc(doc(db, 'users', resolvedUid), {
          notes: trimmedNotes,
          notesUpdatedAt: updatedTimestamp,
          notesUpdatedBy: updaterName
        });

        setUsers(prev => prev.map(u => u.uid === resolvedUid ? {
          ...u,
          notes: trimmedNotes,
          notesUpdatedAt: updatedTimestamp,
          notesUpdatedBy: updaterName
        } : u));
      } else if (selectedClientDetail) {
        // Create or merge new lead doc
        const newUid = selectedClientDetail.userId || ('lead_' + (selectedClientDetail.phone || Date.now()).toString().replace(/[^a-zA-Z0-9_]/g, '_'));
        await setDoc(doc(db, 'users', newUid), {
          uid: newUid,
          name: selectedClientDetail.name || 'عميل محتمل',
          email: selectedClientDetail.email !== 'غير متوفر' ? selectedClientDetail.email : '',
          phone: selectedClientDetail.phone || '',
          role: 'client',
          createdAt: new Date().toISOString(),
          notes: trimmedNotes,
          notesUpdatedAt: updatedTimestamp,
          notesUpdatedBy: updaterName
        }, { merge: true });

        setUsers(prev => {
          const exists = prev.some(u => u.uid === newUid);
          if (exists) {
            return prev.map(u => u.uid === newUid ? {
              ...u,
              notes: trimmedNotes,
              notesUpdatedAt: updatedTimestamp,
              notesUpdatedBy: updaterName
            } : u);
          }
          return [...prev, {
            uid: newUid,
            name: selectedClientDetail.name || 'عميل محتمل',
            email: selectedClientDetail.email !== 'غير متوفر' ? selectedClientDetail.email : '',
            phone: selectedClientDetail.phone || '',
            role: 'client',
            createdAt: new Date().toISOString(),
            notes: trimmedNotes,
            notesUpdatedAt: updatedTimestamp,
            notesUpdatedBy: updaterName
          }];
        });
      }

      if (selectedUserDetail) {
        setSelectedUserDetail((prev: any) => prev ? {
          ...prev,
          notes: trimmedNotes,
          notesUpdatedAt: updatedTimestamp,
          notesUpdatedBy: updaterName
        } : null);
      }

      if (selectedClientDetail) {
        setSelectedClientDetail((prev: any) => prev ? {
          ...prev,
          notes: trimmedNotes,
          notesUpdatedAt: updatedTimestamp,
          notesUpdatedBy: updaterName
        } : null);
      }

      setLeadNotesSaveSuccess(true);
      setTimeout(() => setLeadNotesSaveSuccess(false), 4000);
    } catch (err) {
      console.error("Error saving broker notes:", err);
      alert("حدث خطأ أثناء حفظ ملاحظات الوسيط.");
    } finally {
      setIsSavingLeadNotes(false);
    }
  };

