  const handleToggleUserBlock = async (userId: string, currentBlocked: boolean) => {
    if (userId === auth.currentUser?.uid) {
      alert("❌ لا يمكنك حظر حسابك الشخصي!");
      return;
    }
    const targetUser = users.find(u => u.uid === userId);
    const userName = targetUser?.name || "مستخدم مجهول";
    setUserConfirmAction({
      type: currentBlocked ? 'unblock' : 'block',
      userId,
      userName
    });
    setConfirmReason(currentBlocked ? "" : "مخالفة شروط الاستخدام");
  };

  const handleConfirmActionExecute = async () => {
    if (!userConfirmAction) return;
    const { type, userId, userName } = userConfirmAction;
    setUserConfirmAction(null);

    if (type === 'delete') {
      try {
        await deleteDoc(doc(db, 'users', userId));
        setUsers(prev => prev.filter(u => u.uid !== userId));
        setSuccessMessage(`🗑️ تم حذف حساب المستخدم "${userName}" نهائياً بنجاح!`);
        setTimeout(() => setSuccessMessage(null), 4000);
        if (selectedUserDetail?.uid === userId) {
          setSelectedUserDetail(null);
        }
      } catch (err) {
        console.error("Error deleting user document:", err);
        alert("فشل في حذف المستخدم من قاعدة البيانات.");
      }
    } else {
      const newBlocked = type === 'block';
      const isVerified = type === 'verify';
      const reason = newBlocked ? confirmReason.trim() : "";
      try {
        if (type === 'verify') {
          await updateDoc(doc(db, 'users', userId), { 
            isVerified: true
          });
          setUsers(prev => prev.map(u => u.uid === userId ? { ...u, isVerified: true } : u));
          setSuccessMessage(`✅ تم توثيق هوية المستخدم "${userName}" بنجاح!`);
          setTimeout(() => setSuccessMessage(null), 4000);
          if (selectedUserDetail?.uid === userId) {
            setSelectedUserDetail(prev => prev ? { ...prev, isVerified: true } : null);
          }
        } else {
          await updateDoc(doc(db, 'users', userId), { 
            blocked: newBlocked,
            blockReason: reason
          });
          setUsers(prev => prev.map(u => u.uid === userId ? { ...u, blocked: newBlocked, blockReason: reason } : u));
          setSuccessMessage(newBlocked ? `🔒 تم حظر المستخدم "${userName}" بنجاح ومنعه من الدخول!` : `🔓 تم إلغاء حظر المستخدم "${userName}" بنجاح وإعادة تفعيل حسابه!`);
          setTimeout(() => setSuccessMessage(null), 4000);
          
          if (selectedUserDetail?.uid === userId) {
            setSelectedUserDetail(prev => prev ? { ...prev, blocked: newBlocked, blockReason: reason } : null);
          }
        }
      } catch (err) {
        console.error("Error toggling user status:", err);
        alert("فشل في تعديل حالة المستخدم وتحديث المستند.");
      }
    }
  };

