  const handleManualBlockUserByInput = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!manualBlockEmailOrUid.trim()) {
      alert("الرجاء إدخال البريد الإلكتروني أو معرّف المستخدم (UID) أولاً!");
      return;
    }

    const targetInput = manualBlockEmailOrUid.trim().toLowerCase();
    const adminEmail = auth.currentUser?.email?.toLowerCase() || '';
    const adminUid = auth.currentUser?.uid || '';
    
    if (targetInput === adminEmail || targetInput === adminUid) {
      alert("❌ لا يمكنك حظر نفسك يدوياً!");
      return;
    }

    setIsProcessingManualBlock(true);
    try {
      // 1. Look in the local loaded users list first
      let targetUser = users.find(u => 
        (u.email && u.email.toLowerCase() === targetInput) || 
        (u.uid && u.uid === targetInput)
      );

      // 2. If not found in the local list, query Firestore directly to be absolutely sure
      if (!targetUser) {
        // Query by email
        const qEmail = query(collection(db, 'users'), where('email', '==', targetInput));
        const emailSnap = await getDocs(qEmail);
        if (!emailSnap.empty) {
          const docSnap = emailSnap.docs[0];
          targetUser = { uid: docSnap.id, ...docSnap.data() };
        } else {
          // Try checking if the input is a valid UID by doing a direct getDoc
          const docRef = doc(db, 'users', manualBlockEmailOrUid.trim());
          const docSnap = await getDoc(docRef);
          if (docSnap.exists()) {
            targetUser = { uid: docSnap.id, ...docSnap.data() };
          }
        }
      }

      const reason = manualBlockReason.trim() || 'تم الحظر يدوياً من لوحة التحكم';

      if (targetUser) {
        // Found user!
        if (targetUser.blocked) {
          alert("⚠️ هذا المستخدم محظور بالفعل في النظام!");
          setIsProcessingManualBlock(false);
          return;
        }

        const confirmBlock = window.confirm(`هل أنت متأكد من حظر حساب المستخدم: ${targetUser.name || 'مجهول'} (${targetUser.email || 'بدون بريد'}) يدوياً؟`);
        if (!confirmBlock) {
          setIsProcessingManualBlock(false);
          return;
        }

        await updateDoc(doc(db, 'users', targetUser.uid), { 
          blocked: true,
          blockReason: reason
        });

        // Update local state
        setUsers(prev => {
          const exists = prev.some(u => u.uid === targetUser.uid);
          if (exists) {
            return prev.map(u => u.uid === targetUser.uid ? { ...u, blocked: true, blockReason: reason } : u);
          } else {
            return [...prev, { ...targetUser, blocked: true, blockReason: reason }];
          }
        });

        setManualBlockEmailOrUid('');
        setManualBlockReason('');
        setSuccessMessage(`🔒 تم حظر المستخدم ${targetUser.name || targetUser.email} بنجاح!`);
        setTimeout(() => setSuccessMessage(null), 4000);
      } else {
        // Unregistered user / Not found email, create pre-blacklist entry!
        const confirmPreBlock = window.confirm(`لم يتم العثور على حساب مسجل حالياً بالبريد/المعرّف "${manualBlockEmailOrUid.trim()}".\n\nهل تفضل إنشاء ملف حظر مسبق يدوياً، بحيث يتم حظره تلقائياً فور قيامه بالتسجيل أو استخدام المنصة؟`);
        if (!confirmPreBlock) {
          setIsProcessingManualBlock(false);
          return;
        }

        const isEmail = manualBlockEmailOrUid.includes('@');
        const customDocId = isEmail ? `blocked_email_${targetInput.replace(/[^a-z0-9]/g, '_')}` : manualBlockEmailOrUid.trim();

        const placeholderProfile = {
          uid: customDocId,
          email: isEmail ? targetInput : '',
          name: 'مستخدم محظور يدوياً (قبل التسجيل)',
          role: 'client',
          blocked: true,
          blockReason: reason,
          createdAt: new Date().toISOString()
        };

        // If it's a UID, write directly to that UID document
        const targetDocRef = doc(db, 'users', isEmail ? customDocId : manualBlockEmailOrUid.trim());
        await setDoc(targetDocRef, placeholderProfile);

        // Update local state
        setUsers(prev => [...prev, placeholderProfile]);

        setManualBlockEmailOrUid('');
        setManualBlockReason('');
        setSuccessMessage(`🚫 تم إنشاء حظر مسبق للبريد/المعرّف وتخزينه بنجاح لتقييده فور دخوله!`);
        setTimeout(() => setSuccessMessage(null), 5000);
      }
    } catch (err) {
      console.error("Error manual blocking user:", err);
      alert("حدث خطأ أثناء محاولة حظر المستخدم يدوياً.");
    } finally {
      setIsProcessingManualBlock(false);
    }
  };

  const handleCreateAdmin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAddingAdmin(true);
    setAddAdminError(null);

    if (!newAdminName || !newAdminEmail || !newAdminPassword) {
      setAddAdminError("الرجاء ملء جميع الحقول المطلوبة (الاسم، البريد الإلكتروني، كلمة المرور)");
      setIsAddingAdmin(false);
      return;
    }

    if (newAdminPassword.length < 6) {
      setAddAdminError("يجب أن تكون كلمة المرور 6 أحرف على الأقل");
      setIsAddingAdmin(false);
      return;
    }

    const secondaryAppName = `adminApp_${Date.now()}`;
    let secondaryApp;
    
    try {
      secondaryApp = initializeApp(firebaseConfig, secondaryAppName);
      
      const secondaryAuth = getAuth(secondaryApp);
      
      const userCredential = await createUserWithEmailAndPassword(secondaryAuth, newAdminEmail, newAdminPassword);
      const newUser = userCredential.user;

      try {
        await sendEmailVerification(newUser);
      } catch (verifyErr) {
        console.warn("Failed to send verification email:", verifyErr);
      }

      const userDocRef = doc(db, 'users', newUser.uid);
      const newAdminData = {
        uid: newUser.uid,
        email: newAdminEmail.toLowerCase(),
        name: newAdminName,
        role: 'admin',
        broker: 'مباشر',
        phone: newAdminPhone.trim() || '',
        createdAt: new Date().toISOString()
      };
      
      await setDoc(userDocRef, newAdminData);

      await signOut(secondaryAuth);
      
      setUsers(prev => [newAdminData, ...prev]);

      setNewAdminName('');
      setNewAdminEmail('');
      setNewAdminPassword('');
      setNewAdminPhone('');
      setShowAddAdminModal(false);
      
      alert(`✅ تم إنشاء حساب المشرف "${newAdminName}" بنجاح وتعيينه بامتيازات الإدارة الكاملة!`);
    } catch (err: any) {
      console.error("Error adding admin:", err);
      let errorMsg = "حدث خطأ غير متوقع أثناء إضافة المشرف.";
      if (err.code === 'auth/email-already-in-use') {
        errorMsg = "البريد الإلكتروني المدخل مستخدم بالفعل في حساب آخر.";
      } else if (err.code === 'auth/invalid-email') {
        errorMsg = "صيغة البريد الإلكتروني المدخل غير صحيحة.";
      } else if (err.code === 'auth/weak-password') {
        errorMsg = "كلمة المرور ضعيفة جداً. يجب أن تتكون من 6 أحرف على الأقل.";
      } else {
        errorMsg = err.message || errorMsg;
      }
      setAddAdminError(errorMsg);
    } finally {
      setIsAddingAdmin(false);
      if (secondaryApp) {
        try {
          await deleteApp(secondaryApp);
        } catch (appDelErr) {
          console.error("Secondary app cleanup error:", appDelErr);
        }
      }
    }
  };

