  const handleUpdateProperty = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProperty) return;
    try {
      const docRef = doc(db, 'properties', editingProperty.id);

      // Track and log price changes in the database
      const originalProp = allProperties.find(p => p.id === editingProperty.id);
      if (originalProp) {
        // Log status change if one has occurred
        if (originalProp.status !== editingProperty.status) {
          try {
            const logRef = doc(collection(db, 'property_status_log'));
            await setDoc(logRef, {
              id: logRef.id,
              propertyId: editingProperty.id,
              propertyTitle: editingProperty.title,
              governorate: editingProperty.governorate || 'دمشق',
              oldStatus: originalProp.status || 'available',
              newStatus: editingProperty.status || 'available',
              updatedAt: new Date().toISOString()
            });
          } catch (logErr) {
            console.error("Error logging status update in handleUpdateProperty:", logErr);
          }
        }

        const parseDigits = (s: string) => {
          if (!s) return 0;
          const clean = s.replace(/[^\d]/g, '');
          const parsed = parseInt(clean, 10);
          return isNaN(parsed) ? 0 : parsed;
        };
        const oldPriceNum = parseDigits(originalProp.price);
        const newPriceNum = parseDigits(editingProperty.price);

        if (oldPriceNum !== newPriceNum && oldPriceNum > 0 && newPriceNum > 0) {
          try {
            const logRef = doc(collection(db, 'price_updates_log'));
            await setDoc(logRef, {
              id: logRef.id,
              propertyId: editingProperty.id,
              propertyTitle: editingProperty.title,
              governorate: editingProperty.governorate || 'دمشق',
              oldPrice: oldPriceNum,
              newPrice: newPriceNum,
              updatedAt: new Date().toISOString()
            });

            // If the price decreased, notify all users who enabled notifications for this property
            if (newPriceNum < oldPriceNum) {
              const usersSnapshot = await getDocs(collection(db, 'users'));
              const usersList: any[] = [];
              usersSnapshot.forEach((docSnap) => {
                usersList.push({ uid: docSnap.id, ...docSnap.data() });
              });

              for (const u of usersList) {
                const favDocRef = doc(db, 'users', u.uid, 'favorites', editingProperty.id);
                const favDocSnap = await getDoc(favDocRef);
                if (favDocSnap.exists()) {
                  const favData = favDocSnap.data();
                  if (favData.priceDropAlertEnabled) {
                    const notificationId = `price_drop_${u.uid}_${editingProperty.id}_${Date.now()}`;
                    await setDoc(doc(db, 'notifications', notificationId), {
                      userId: u.uid,
                      title: `📉 انخفاض سعر عقار في مفضلتك!`,
                      message: `خبر سار! انخفض سعر العقار "${editingProperty.title}" في مفضلتك من ${originalProp.price} إلى ${editingProperty.price}. اضغط هنا للتفاصيل الفورية!`,
                      status: 'unread',
                      type: 'price_drop_alert',
                      propertyId: editingProperty.id,
                      createdAt: new Date().toISOString()
                    });

                    // Trigger Automated WhatsApp alert message
                    const phone = u.phone || "0945430030";
                    const messageText = `مرحباً ${u.name || 'عميلنا العزيز'}، نود إعلامك بأن العقار "${editingProperty.title}" في قائمتك المفضلة قد انخفض سعره الآن من ${originalProp.price} لـ ${editingProperty.price}! فرصة مميزة للشراء الآن. شركة البراء النعيمي للتسويق العقاري.`;

                    await authFetch("/api/whatsapp/send", {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({ phone, message: messageText })
                    }).catch(apiErr => console.error("Express WhatsApp price drop failed:", apiErr));

                    // Store log in whatsapp_logs
                    const waLogRef = doc(collection(db, 'whatsapp_logs'));
                    await setDoc(waLogRef, {
                      id: waLogRef.id,
                      sender: "0945430030",
                      receiverName: u.name || 'عميلنا العزيز',
                      receiverPhone: phone,
                      receiverEmail: u.email || "غير محدد",
                      propertyId: editingProperty.id,
                      propertyTitle: editingProperty.title,
                      message: messageText,
                      status: 'success',
                      createdAt: new Date().toISOString()
                    }).catch(logErr => console.error("price drop whatsapp log error:", logErr));
                  }
                }
              }
            }
          } catch (logErr) {
            console.error("Error handling price update log & notifications:", logErr);
          }
        }
      }

      // Check if broker assignment changed and notify if enabled
      try {
        const originalProp = allProperties.find(p => p.id === editingProperty.id);
        if (originalProp) {
          const originalBrokerId = originalProp.brokerId || '';
          const newBrokerId = editingProperty.brokerId || '';

          if (newBrokerId && newBrokerId !== originalBrokerId && isBrokerAssignedWaNotifEnabled) {
            const broker = brokers.find(b => b.id === newBrokerId);
            if (broker) {
              const template = renderTemplate('broker_assigned', {
                broker: broker.name,
                property: editingProperty.title,
                governorate: editingProperty.governorate || 'دمشق',
                price: editingProperty.price
              });
              await triggerBrokerWhatsAppNotification(broker, template.message, editingProperty.id, editingProperty.title);
            }
          }
        }
      } catch (waErr) {
        console.error("Failed to notify broker on assignment update:", waErr);
      }

      const cleanProps = { ...editingProperty };
      delete (cleanProps as any).id;
      
      await setDoc(docRef, {
        ...cleanProps,
        updatedAt: new Date().toISOString()
      }, { merge: true });
      
      setEditingProperty(null);
      onUpdateProperties();
      setSuccessMessage(`تم تحديث بيانات العقار بنجاح! 🎉`);
      setTimeout(() => setSuccessMessage(null), 5000);
    } catch (err: any) {
      console.error("Error updating property details:", err);
      alert("فشل في تحديث بيانات العقار.");
    }
  };

  const isPropertyMatchingSearch = (property: Partial<Property>, searchData: any) => {
    // Check Governorate Filter
    if (searchData.governorate && searchData.governorate !== 'الكل') {
      if (property.governorate !== searchData.governorate) return false;
    }
    
    // Check Property Type Filter
    if (searchData.propertyType && searchData.propertyType !== 'الكل') {
      if (property.type !== searchData.propertyType) return false;
    }
    
    // Check Rooms Filter
    if (searchData.rooms && searchData.rooms !== 'الكل') {
      const roomsVal = property.rooms || 0;
      if (searchData.rooms === '5+') {
        if (roomsVal < 5) return false;
      } else {
        if (String(roomsVal) !== searchData.rooms) return false;
      }
    }
    
    // Check Min Price / Max Price (Note: prices are in Billion, stored as strings. We check numeric comparison)
    const propPriceNumeric = parseFloat(property.price || '0') || 0;
    if (searchData.minPrice && searchData.minPrice !== '') {
      if (propPriceNumeric < parseFloat(searchData.minPrice)) return false;
    }
    if (searchData.maxPrice && searchData.maxPrice !== '') {
      if (propPriceNumeric > parseFloat(searchData.maxPrice)) return false;
    }
    
    // Check search query (keyword match on title or description)
    if (searchData.searchQuery && searchData.searchQuery.trim() !== '') {
      const q = searchData.searchQuery.toLowerCase().trim();
      const titleMatch = property.title?.toLowerCase().includes(q);
      const descMatch = property.description?.toLowerCase().includes(q);
      const locMatch = property.location?.toLowerCase().includes(q);
      if (!titleMatch && !descMatch && !locMatch) return false;
    }
    
    return true;
  };

  const handleCreateProperty = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const addedDoc = await addDoc(collection(db, 'properties'), {
        ...newProperty,
        createdAt: new Date().toISOString()
      });
      const propertyId = addedDoc.id;
      
      // Dispatch alerts/notifications to user-subscribers
      const gov = newProperty.governorate || 'دمشق';
      try {
        const usersQuery = query(collection(db, 'users'), where('alertGovernorates', 'array-contains', gov));
        const querySnap = await getDocs(usersQuery);
        const alertedUserIds = new Set<string>();

        const alertPromises = querySnap.docs.map(docSnap => {
          const uId = docSnap.id;
          alertedUserIds.add(uId);
          const notificationId = `alert_${uId}_${propertyId}_${Date.now()}`;
          return setDoc(doc(db, 'notifications', notificationId), {
            userId: uId,
            title: `عقار جديد في محافظة ${gov} 🔔`,
            message: `تم إضافة عقار مميز جديد في ${gov}: "${newProperty.title}". اضغط هنا لمعاينة التفاصيل والأسعار الفورية!`,
            status: 'unread',
            type: 'property_alert',
            propertyId: propertyId,
            createdAt: new Date().toISOString()
          });
        });
        await Promise.all(alertPromises);

        // Also dispatch to users with matching saved searches that enable alerts
        const savedSearchesQuery = query(collection(db, 'saved_searches'), where('alertsEnabled', '==', true));
        const savedSearchesSnap = await getDocs(savedSearchesQuery);
        
        const matchedUserIds = new Set<string>();
        savedSearchesSnap.docs.forEach(docSnap => {
          const searchData = docSnap.data();
          if (isPropertyMatchingSearch(newProperty, searchData)) {
            if (!alertedUserIds.has(searchData.userId)) {
              matchedUserIds.add(searchData.userId);
            }
          }
        });

        // Skip alerting the creator if they are in the list
        if (auth.currentUser) {
          matchedUserIds.delete(auth.currentUser.uid);
        }

        const savedSearchAlertPromises = Array.from(matchedUserIds).map(uId => {
          const notificationId = `search_alert_${uId}_${propertyId}_${Date.now()}`;
          return setDoc(doc(db, 'notifications', notificationId), {
            userId: uId,
            title: `🔔 عقار جديد يطابق تصفيتك المفضلة!`,
            message: `عقار جديد يطابق معايير بحثك المحفوظة: "${newProperty.title}". اضغط لمعاينته الآن!`,
            status: 'unread',
            type: 'property_alert',
            propertyId: propertyId,
            createdAt: new Date().toISOString()
          });
        });
        await Promise.all(savedSearchAlertPromises);

      } catch (err) {
        console.error("Failed to dispatch property alerts to subscribers:", err);
      }

      // Send WhatsApp to broker if assigned and option is enabled
      try {
        if (newProperty.brokerId && isBrokerAssignedWaNotifEnabled) {
          const broker = brokers.find(b => b.id === newProperty.brokerId);
          if (broker) {
            const template = renderTemplate('broker_assigned', {
              broker: broker.name,
              property: newProperty.title,
              governorate: newProperty.governorate || 'دمشق',
              price: newProperty.price
            });
            await triggerBrokerWhatsAppNotification(broker, template.message, propertyId, newProperty.title);
          }
        }
      } catch (waErr) {
        console.error("Failed to send WhatsApp notification to broker on creation:", waErr);
      }

      setIsAddingProperty(false);
      onUpdateProperties();
      setNewProperty({
        title: '',
        price: '',
        location: '',
        description: '',
        type: 'Residential',
        rooms: 3,
        status: 'available',
        images: ['https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=800&q=80'],
        coordinates: [33.51, 36.27],
        isExclusive: false,
        exclusiveStart: '',
        exclusiveEnd: '',
        exclusiveMarketingDetails: '',
        governorate: 'دمشق',
        addedServices: []
      });
    } catch (e) {
      handleFirestoreError(e, 'create', 'properties');
    }
  };

