                                    noti.type === 'booking' ? "bg-emerald-50 text-emerald-700 border-emerald-200" :
                                    noti.type === 'cancellation' ? "bg-stone-50 text-stone-700 border-stone-200" :
                                    noti.type === 'general' ? "bg-blue-50 text-blue-700 border-blue-200" :
                                    noti.type === 'appointment_accepted' ? "bg-teal-50 text-teal-700 border-teal-200" :
                                    "bg-zinc-100 text-zinc-700 border-zinc-200"
