                                <div className="text-left">
                                  <span className="text-[10px] text-zinc-400 block font-bold">العمولة التقديرية</span>
                                  <span className="font-black text-emerald-600 font-mono">
                                    {client.expectedCommission ? client.expectedCommission.toLocaleString('en-US') + ' ل.س' : '0 ل.س'}
                                  </span>
                                </div>
